sys_variable_value.value:
(function execute(inputs, outputs) {

var instance = gs.getProperty('instance_name');

outputs.instance_url_link = 'https://' + instance + '.servicenowservices.com';

    if(inputs.status_code != 200){
     var responseBody = JSON.parse(inputs.response_body);

       var errText = 'Failed to create the reservation. Error: ';
        outputs.responsebody= errText + responseBody.error.message;
    }
if(inputs.status_code == 200){
    var responseBody = JSON.parse(inputs.response_body);
        outputs.number= responseBody.result.parent;
}
})(inputs, outputs);

